mapper.select:
SELECT ad.camera_name as 'name', COUNT(ad.camera_id) as 'value' FROM `alarm_detail` ad INNER JOIN `ky_category` kc ON ad.alarm_type = kc.code
and ad.camera_id in
#{cameraId}
and kc.id in
#{category}
and ad.alarm_time between #{startTime} and #{endTime}
and ad.alarm_level!='0'
GROUP BY ad.camera_name ORDER BY value DESC

SELECT kc.name as 'name', kc.id as 'areaId', COUNT(ad.alarm_area) as 'value' FROM `alarm_detail` ad INNER JOIN `ky_category` kc ON ad.alarm_area = kc.id
and ad.camera_id in
#{cameraId}
and kc.id in
#{category}
and ad.alarm_time between #{startTime} and #{endTime}
and ad.alarm_level!='0'
GROUP BY kc.id, kc.name ORDER BY value DESC

SELECT kc.name as 'name', COUNT(ad.alarm_type) as 'value'
FROM `alarm_detail` ad
INNER JOIN `ky_category` kc ON ad.alarm_type = kc.code


        and ad.camera_id in

            #{cameraId}



        and kc.id in

            #{category}



        and ad.alarm_time between #{startTime} and #{endTime}

    and ad.alarm_level!='0'

GROUP BY kc.id, kc.name

SELECT a.hour hour, ifnull(sum(b.count), 0) value FROM (SELECT 0 hour UNION ALL SELECT 1 hour UNION ALL SELECT 2 hour UNION ALL SELECT 3 hour UNION ALL SELECT 4 hour UNION ALL SELECT 5 hour UNION ALL SELECT 6 hour UNION ALL SELECT 7 hour UNION ALL SELECT 8 hour UNION ALL SELECT 9 hour UNION ALL SELECT 10 hour UNION ALL SELECT 11 hour UNION ALL SELECT 12 hour UNION ALL SELECT 13 hour UNION ALL SELECT 14 hour UNION ALL SELECT 15 hour UNION ALL SELECT 16 hour UNION ALL SELECT 17 hour UNION ALL SELECT 18 hour UNION ALL SELECT 19 hour UNION ALL SELECT 20 hour UNION ALL SELECT 21 hour UNION ALL SELECT 22 hour UNION ALL SELECT 23 hour) a LEFT JOIN (SELECT hour(ad.alarm_time) as hour, count(ad.alarm_time) as count FROM `alarm_detail` ad INNER JOIN `ky_category` kc ON ad.alarm_type = kc.code
and ad.camera_id in
#{cameraId}
and kc.id in
#{category}
and ad.alarm_time between #{startTime} and #{endTime}
and ad.alarm_level!='0'
GROUP BY date_format(ad.alarm_time, '%Y%m%d-%H'), hour) as b ON a.hour=b.hour GROUP BY hour

select DATE_FORMAT(ad.alarm_time,'%Y-%m-%d') as 'date', count(if(ad.alarm_level!='0',true,null)) as 'value', count(if(ad.alarm_level='4',true,null)) as 'seriousValue', count(if(ad.alarm_level='3',true,null)) as 'warningValue', count(if(ad.alarm_level='2',true,null)) as 'commonValue', count(if(ad.alarm_level='1',true,null)) as 'remindValue' FROM `alarm_detail` ad INNER JOIN `ky_category` kc ON ad.alarm_type = kc.code
and ad.camera_id in
#{cameraId}
and kc.id in
#{category}
and ad.alarm_time between #{startTime} and #{endTime}
group by DATE_FORMAT(ad.alarm_time,'%Y-%m-%d')

SELECT count(if(ad.alarm_level!='0',true,null)) as allCount, IFNULL(sum(CASE when ad.alarm_level = '1' then 1 else 0 end),0) as remindCount, IFNULL(sum(CASE when ad.alarm_level = '2' then 1 else 0 end),0) as commonCount, IFNULL(sum(CASE when ad.alarm_level = '3' then 1 else 0 end),0) as warningCount, IFNULL(sum(CASE when ad.alarm_level = '4' then 1 else 0 end),0) as seriousCount FROM `alarm_detail` ad INNER JOIN `ky_category` kc ON kc.code = ad.alarm_type
and ad.camera_id in
#{cameraId}
and kc.id in
#{category}
and ad.alarm_time between #{startTime} and #{endTime}

SELECT count(if(ad.alarm_level!='0',true,null)) as allCount
FROM `alarm_detail` ad
INNER JOIN `ky_category` kc ON kc.code = ad.alarm_type


        and ad.camera_id in

